pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, uint8 numTos, uint v) public {
        vm.assume(numTos > 0 && numTos <= 10);
        address[] memory tos = new address[](numTos);
        for (uint i = 0; i < numTos; i++) {
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(from, i)))));
        }
        CallRecorder recorder = new CallRecorder();
        vm.prank(from);
        bool ok;
        try c.transfer(from, address(recorder), tos, v) { ok = true; } catch { ok = false; }
        assertTrue(!ok || recorder.called());
    }
}

contract CallRecorder {
    bool public called;
    function transferFrom(address, address, uint256) external returns (bool) {
        called = true;
        return true;
    }
}
